"""Component p-82af68dd@100000/layers.15.mlp.down_proj:2634.

One rank-one piece of layer 15's MLP down projection. Its input vector is almost entirely MLP
hidden unit 2634, so its activation is that hidden unit's value, scaled by about 1.

What it responds to. Its activation is large in both directions (std 0.46, tails near +/-20), but
it is diffuse and context-dependent: no token list or simple prefix feature predicts it well (token
identity, repetition, position, quotes, newlines, person nouns and the model's own next-token guesses
were all tried). What the strong tails do share is word-level:
  - positive on evaluative judgement words about people and things ("awful", "terrible",
    "boring", "rude", "polite", "disgusting", "iconic", "infamous") and on habitual or generic
    adverbs ("generally", "usually", "typically", "always", "often", "usual"), and most strongly on
    "unlike";
  - negative on degree, focus and sincerity adverbs ("virtually", "truly", "hardly", "literally",
    "practically", "certainly", "almost", "barely", "merely") and mildly on "just", "simply", "only",
    "also", "even", "really", "very".
Every other token gets the component's mean activation.

The program is stateless: it reads only the newest token. Its word lists are the readable part; they
explain only about 0.1% of the variance, so it is close to a constant predictor.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MEAN = -0.04
JUDGEMENT = {
    "awful", "terrible", "horrible", "boring", "dull", "rude", "polite", "disgusting", "brutal",
    "ugly", "annoying", "frustrating", "creepy", "scary", "nasty", "corrupt", "sucks", "iconic",
    "infamous", "handsome",
}
HABITUAL = {
    "generally", "usually", "typically", "always", "often", "normally", "usual", "typical",
    "traditionally", "mostly", "commonly",
}
CONTRAST = {"unlike"}
EMPHATIC = {
    "truly", "literally", "virtually", "practically", "honestly", "hardly", "certainly",
    "absolutely", "almost", "barely", "merely", "totally", "easily", "personally",
}
MILD = {"just", "simply", "really", "actually", "basically", "rather", "quite", "nearly", "only", "also", "even", "very"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    if word in CONTRAST:
        value = 1.2
    elif word in JUDGEMENT:
        value = 0.8
    elif word in HABITUAL:
        value = 0.7
    elif word in EMPHATIC:
        value = -0.5
    elif word in MILD:
        value = -0.15
    else:
        value = MEAN
    return carry, float(value)

"""Decimal-point detector: a negative spike on a '.', ',' or ':' typed straight after a number.

Layer 15's MLP writes a strong negative signal on the separator that continues a number
(the '.' in 3.14, the ',' in 1,000, the ':' in 10:30). Its size depends on what the number
looks like so far:
  - '.' after a number that starts a line (a list item like "2.") is weak;
  - '.' after "$" (money) is the strongest; other '.' after a number are strong;
  - a 4-digit number (a year, "in 1999.") is weak, since its '.' is usually a full stop;
  - the first such '.' in a document is about 1.5 times as strong as later ones;
  - ',' is weak, and ':' is strong only after a 1-2 digit number (a clock time).
Everything else is predicted as 0.
"""

READS = ()

DIGITS = set("0123456789")


def is_digit(tok):
    return len(tok) > 0 and all(ch in DIGITS for ch in tok)


def step(carry, prefix, upstream):
    # carry: (document label, whether a '.' after a number has already occurred in it)
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = len(toks) - 1
    seen = bool(carry) and carry[0] == docs[t] and carry[1]
    cur = toks[t]
    if cur not in (".", ",", ":") or t == 0 or not is_digit(toks[t - 1]):
        return (docs[t], seen), 0.0
    # Length of the digit run just before the separator, and the token before the run.
    run, i = 0, t - 1
    while i >= 0 and docs[i] == docs[t] and is_digit(toks[i]) and run < 9:
        run += 1
        i -= 1
    before = toks[i] if i >= 0 and docs[i] == docs[t] else ""
    if cur == ".":
        if run == 4:
            value = -2.5
        elif "\n" in before:
            value = -2.6
        elif "$" in before:
            value = -17.0
        else:
            value = -9.0
        if not seen:
            value *= 1.5
        seen = True
    elif cur == ",":
        value = -0.3 if run == 4 else -2.0
    else:
        value = 0.0 if run >= 3 else -4.0
    return (docs[t], seen), value

"""Layer 15 MLP down-projection, component 2644: "a bare verb comes next" words.

The component is high on words that set up a bare (uninflected) verb as the next
word, and near zero or negative elsewhere:

- Modal verbs, in English and other languages: can, could, must, may, might, should,
  will, would, shall, cannot, and 能 / 可以 / 必须 / может / peut / puede (about 1.0).
- The infinitive marker "to": high after words that take an infinitive
  (want, try, able, difficult, way, chance, ...), about 1.6; near zero after words
  that take a prepositional "to" (compared, according, due, prior, respect, ...);
  moderate (about 0.85) in other cases, including sentence-initial "To".
- Subject pronouns and relative words, weakly (about 0.25 to 0.45): you, we, they,
  I, he, she, it, who, that, which.
- Negation, weakly (about 0.3): not, never, n't.
- Forms of "be" and a few verbs that take a noun or number next (is, are, was, be,
  been, make, need, ...): slightly negative (about -0.2).

Everything else is 0. Concept lists are short hand-picked sets; the numbers are
least-squares fits on about 8 million training positions. This explains roughly a
tenth of the variance: most of the component's activation depends on context that
no short word list captures.
"""

READS = ()

MODALS = {
    "can", "could", "must", "may", "might", "should", "will", "would", "shall",
    "cannot", "gonna", "'ll", "'d", "'t", "’t", "’ll", "’d", "能", "可以", "会", "要",
    "应该", "必须", "不能", "能够", "才能", "无法", "может", "могут", "должен",
    "peut", "doit", "puede", "pode", "può", "deve",
}
INFINITIVE_WORDS = {  # words that take a to-infinitive
    "want", "wanted", "wants", "like", "love", "need", "needed", "needs", "try",
    "tried", "tries", "trying", "able", "unable", "difficult", "hard", "easy",
    "impossible", "possible", "likely", "unlikely", "supposed", "meant", "intended",
    "plan", "planned", "hope", "wish", "desire", "eager", "glad", "happy", "ready",
    "willing", "decided", "failed", "fail", "way", "ways", "chance", "time",
    "ability", "attempt", "effort", "opportunity", "required", "allowed", "expected",
}
PREP_TO_WORDS = {  # words that take a prepositional "to"
    "compared", "prior", "according", "addition", "respect", "due", "related",
    "relative", "similar", "regard", "refer", "refers", "referred", "relating",
    "connected", "attached", "subject", "opposed", "contribute", "contributes",
    "lead", "leads", "led", "respond", "listen", "add", "proportional",
    "corresponding", "belong", "belongs", "linked", "equal", "equivalent",
}
PRONOUNS = {"you", "i", "we", "they", "he", "she", "it"}
RELATIVES = {"who": 1.0, "that": 0.5, "which": 0.3}
NEGATION = {"not", "never", "n't"}
COPULA = {"is", "are", "was", "were", "be", "been", "being", "am", "make", "need", "get"}


def _word(text):
    return text.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.token_ids) > 1
    same_doc = same_doc and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in MODALS:
        value = 1.0
    elif word == "to":
        if prev in INFINITIVE_WORDS:
            value = 1.6
        elif prev in PREP_TO_WORDS:
            value = 0.1
        else:
            value = 0.85
    elif word in RELATIVES:
        value = RELATIVES[word]
    elif word in PRONOUNS:
        value = 0.25
    elif word in NEGATION:
        value = 0.3
    elif word in COPULA:
        value = -0.2
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP down_proj, component 2650.

What it does: it fires on the first word of a noun phrase that is the object of a
verb or a preposition, i.e. the determiner or possessive that opens the thing being
acted on: "pay [the] bill", "build [your] own", "walk [her] down", "in [the] house".
It is strongest for articles and possessives right after an action verb (about 4-6),
moderate after a preposition (about 2), weak after a copula ("is a", about 0.4) and
about zero after punctuation or a conjunction ("and the", "., the"), at a document
start, or on ordinary content words.

The program looks only at the current token and the word before it, and uses a
small table of expected values for each pairing of word classes.
"""

from collections.abc import Mapping

import wordnet

READS: tuple[str, ...] = ()

ARTICLES = {"the", "a", "an"}
POSSESSIVES = {"her", "his", "their", "your", "my", "our", "its", "thy"}
DETERMINERS = {
    "this", "that", "these", "those", "some", "any", "each", "every",
    "all", "both", "such", "more",
}
OBJECT_PRONOUNS = {"it", "them", "him", "me", "us", "you"}
PREPOSITIONS = {
    "of", "in", "to", "for", "with", "by", "at", "from", "on", "into", "about",
    "over", "under", "through", "between", "during", "after", "before", "within",
    "among", "beyond", "against", "across", "toward", "towards", "upon",
}
COPULAS = {"is", "was", "are", "were", "be", "been", "being", "am"}
CONJUNCTIONS = {"and", "or", "but", "so", "as", "than"}

# Expected activation of each kind of token, by the class of the word before it.
VALUES = {
    "article": {"verb": 4.5, "prep": 2.1, "cop": 0.4, "other": 1.0, "conj": -0.1},
    "possessive": {"verb": 5.8, "prep": 2.2, "cop": 1.1, "other": 1.6, "conj": -0.3},
    "determiner": {"verb": 2.1, "prep": 1.1, "cop": 0.6, "other": 0.3, "conj": -0.3},
    "object_pronoun": {"verb": 1.7, "prep": 0.6, "cop": 0.7, "other": 0.5, "conj": 0.2},
    "preposition": {"verb": -0.2, "prep": -0.5, "cop": -0.5, "other": -0.3, "conj": -0.1},
    "other": {"verb": 0.2, "prep": 0.0, "cop": 0.1, "other": 0.05, "conj": 0.05},
}


def token_kind(word):
    if word in ARTICLES:
        return "article"
    if word in POSSESSIVES:
        return "possessive"
    if word in DETERMINERS:
        return "determiner"
    if word in OBJECT_PRONOUNS:
        return "object_pronoun"
    if word in PREPOSITIONS:
        return "preposition"
    return "other"


def word_class(word):
    if word in PREPOSITIONS:
        return "prep"
    if word in COPULAS:
        return "cop"
    if word == "" or word in CONJUNCTIONS or not any(ch.isalnum() for ch in word):
        return "conj"
    if word.isalpha() and "verb" in wordnet.parts_of_speech(word):
        return "verb"
    return "other"


def step(carry, prefix, upstream: Mapping):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    kind = token_kind(word)
    return carry, VALUES[kind][word_class(before)]

"""Layer 15 MLP unit 2658 (down_proj component 2658), read word by word.

This component is essentially MLP hidden unit 2658 of layer 15, scaled. Its sign depends on
what the current word is doing:

- Negative on words that limit or persist ("only", "merely", "solely", "still", "remain",
  "stay", "too", "just", "mostly"), and more negative on "to/into/onto" right after a verb
  of change or movement ("moved to", "switched to", "relegated to", "returned to").
- Mildly negative on auxiliaries and copulas ("is", "are", "be", "will", "can", "to"), and a
  bit more so when a pronoun like "this" or "it" comes right before ("this is", "it is"),
  the spot where "not" or a negative verdict often follows.
- Positive on words that set up an exception, exclusion or contrast ("except", "excluding",
  "unlike", "outside", "lack", "absent", "without", "opposed"), and mildly positive on
  negation and comparison words ("not", "non", "never", "than", "other", "else").
- Zero elsewhere.

The word-level rules are all this program uses. They explain only a few percent of the
component's variance: most of its variance comes from context that a short word list cannot
capture, so the predictions are weak, though their sign is usually right.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

LIMITING = {
    "only", "merely", "solely", "purely", "mostly", "largely", "mainly", "primarily",
    "simply", "still", "remain", "remains", "remained", "stay", "stays", "stayed", "too",
    "relatively", "entirely", "kept", "become", "becomes", "just", "very", "more",
}
CHANGE_VERBS = {
    "moved", "switched", "changed", "returned", "return", "restricted", "forced", "reduced",
    "transferred", "turned", "converted", "shifted", "went", "go", "move", "back",
    "relegated", "confined",
}
MOVE_PREPOSITIONS = {"to", "into", "onto"}
AUXILIARIES = {
    "to", "is", "are", "was", "were", "be", "been", "will", "would", "should", "can",
    "could", "may", "might", "must", "have", "has", "had",
}
SUBJECT_PRONOUNS = {"this", "it", "itself", "that", "which", "but", "there"}
EXCEPTION = {
    "except", "excluding", "unlike", "outside", "lack", "absent", "anti", "opposed",
    "contrary", "without", "beyond", "barring", "whereas", "although",
}
NEGATION_OR_COMPARISON = {"not", "non", "never", "cannot", "no", "than", "other", "else"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    if word in MOVE_PREPOSITIONS and previous in CHANGE_VERBS:
        value = -2.1
    elif word in MOVE_PREPOSITIONS and previous in AUXILIARIES:
        value = -0.7
    elif word in LIMITING:
        value = -1.4
    elif word in AUXILIARIES:
        value = -0.5 if previous in SUBJECT_PRONOUNS else -0.3
    elif word in EXCEPTION:
        value = 0.7
    elif word in NEGATION_OR_COMPARISON:
        value = 0.45
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 2663 (of Qwen3-1.7B), as a word-class rule.

What it does: this component is positive on the main verbs of a clause, and most
strongly on a verb that comes right after a modal, "to", or a negation ("can't wait",
"to lose", "would die"), i.e. where the verb is about to take an object or particle such
as "everything", "them" or "up". Verb particles ("give up", "away") and verb endings
("-ed", "-ing" pieces) are also positive. It is negative on words that open a new phrase
or clause: subject pronouns, relative and wh-words, prepositions, determiners and "or".
Everything else sits near a small positive level, and nouns sit at zero.

Why: a logit-lens read of its output direction pushes the next-token distribution toward
total/complete words ("everything", "all", "absolutely", "anything") and away from partial
ones ("somewhat", "partly"). Its input reads mostly MLP hidden unit 2663 (its largest
single weight). Word classes explain only about 7% of its variance: the rest is context
that a word list cannot capture.

Main rule: value = class level, looked up from the current word and the word before it.
"""
from functools import lru_cache

import wordnet

READS = ()

# Words that open a new noun phrase or clause: negative.
SUBJECT_PRONOUNS = {"i", "you", "we", "they", "he", "she", "it"}
RELATIVE_WH = {"that", "which", "who", "whom", "what", "when", "where"}
PREPOSITIONS = {"of", "in", "to", "for", "on", "at", "as", "with", "from", "by", "about", "into"}
DETERMINERS = {"a", "an", "this", "these", "those"}
COORDINATORS = {"or", "also"}
OPENERS = SUBJECT_PRONOUNS | RELATIVE_WH | PREPOSITIONS | DETERMINERS | COORDINATORS

# Words after which a bare verb follows: "to lose", "will die", "can't wait".
SETUPS = {"to", "will", "would", "can", "could", "must", "should", "may", "might",
          "not", "never", "n't", "'t", "’t", "'ll", "’ll"}

# Verb particles and verb-ending pieces: positive.
PARTICLES = {"up", "out", "down", "away", "off", "back", "over", "through", "without", "than"}
VERB_ENDINGS = {"ed", "ing", "es"}

AUXILIARIES = {"be", "is", "are", "was", "were", "been", "being", "am",
               "have", "has", "had", "do", "does", "did"}


@lru_cache(maxsize=None)
def word_class(word):
    """WordNet's view of a word: auxiliary, main verb, verb-or-noun, noun or other."""
    parts = wordnet.parts_of_speech(word) if word.isalpha() else frozenset()
    if word in AUXILIARIES:
        return "aux"
    if "verb" in parts and "noun" not in parts:
        return "verb"
    if "verb" in parts:
        return "verb_or_noun"
    if "noun" in parts:
        return "noun"
    return "other"


def step(carry, prefix, upstream):
    """The activation at this position, from the current word and the word before it."""
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    after_setup = prev in SETUPS

    if word in OPENERS:
        value = -0.25
    elif word in PARTICLES or word in VERB_ENDINGS:
        value = 1.0
    else:
        kind = word_class(word)
        if kind == "verb":
            value = 2.1 if after_setup else 1.05
        elif kind == "verb_or_noun":
            value = 1.4 if after_setup else 0.2
        elif kind == "noun":
            value = 0.0
        else:
            value = 0.1
    return None, float(value)

"""Layer 15, MLP hidden unit 2669 (this component is that unit's down_proj column, scaled).

Plain-terms summary: the unit switches on when the text is about people, and its sign and
size depend on the word:
- chat and speaker labels ('assistant', 'speaker') are strongly positive;
- other person words (user, person, friend, child, the anonymised placeholder NAME, and kin
  such as mother or daughter) are mildly positive;
- gendered words agree with the gender balance of the text so far in their document: he/him/
  his are positive when the text has mostly been about men and negative when mostly about
  women; she/her/woman are negative, less so when the text has mostly been about women;
- everything else, including most nouns and punctuation, is near zero.

The program predicts this from the current word and a decaying gender balance per document.
It is a readable approximation: on held-out rows it explains about 3% of the variance.
Most of the remaining variance is context-driven (how person-centred the passage is, and a
sign that depends on the wider sentence), which word lists do not capture.
"""

READS = ()

CHAT_LABELS = {"assistant", "speaker"}
PERSON = {"user", "person", "friend", "baby", "boss", "doctor", "officer", "attorney", "counsel",
          "judge", "defendant", "examiner", "opponent", "child", "NAME"}
KIN = {"mother", "father", "daughter", "son", "sister", "brother", "cousin", "aunt", "uncle",
       "mom", "dad"}
FEMALE = {"she", "her", "hers", "herself", "woman", "women", "girl", "wife", "ms", "mrs", "lady"}
MALE = {"he", "him", "his", "himself", "man", "men", "boy", "husband", "mr"}
DECAY = 0.97  # how fast the gender balance of earlier text fades


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw if raw == "NAME" else raw.lower()
    doc = prefix.document_ids[-1]
    balance = 0.0  # female minus male words so far in this document, decayed
    if carry is not None and carry[1] == doc:
        balance = carry[0]
    clipped = max(-4.0, min(4.0, balance))
    if word in FEMALE:
        value = -1.5 + 0.9 * clipped
    elif word in MALE:
        value = -0.4 - 0.6 * clipped
    elif word in CHAT_LABELS:
        value = 4.5
    elif word in PERSON or word in KIN:
        value = 1.6
    else:
        value = 0.0
    sign = 1.0 if word in FEMALE else -1.0 if word in MALE else 0.0
    return (DECAY * balance + sign, doc), value
